mapper.select:
SELECT mt.* FROM
micro_technology mt
JOIN micro_product mp ON mt.product_id = mp.id AND mt.tenant_code = mp.tenant_code
WHERE mt.active_flag = '1'


        AND mp.product_name =#{productId}


        AND mp.product_seq =#{productSeq}


        AND mp.product_code =#{productCode}

SELECT a.id, mt.id AS techId, mt.product_id AS productId, m.product_seq AS productSeq, m.product_name AS productName, a.process_id AS processId, a.parent_process_id AS parentProcessId, a.process_seq AS processSeq, a.process_code AS processCode, a.parent_process_seq AS parentProcessSeq, IF(a.is_last_process IS NULL,'1',a.is_last_process) AS isLastProcess, a.process_name as processName, a.sort, mt.created_date as createdDate, mt.tech_pattern as techPattern, mt.tech_type as techType, mt.tech_name as techName FROM micro_technology mt INNER JOIN (select mp.id,mp.tech_id,mp.process_id,mp.parent_process_id,mp.process_seq,mp.parent_process_seq,mp.is_last_process,mpc.process_name,mp.tenant_code,mp.process_code, mp.sort from micro_process_chain mp left join micro_process_common mpc on mp.process_id = mpc.id and mp.tenant_code =mpc.tenant_code ) as a ON mt.tenant_code = a.tenant_code AND mt.id = a.tech_id left join micro_product m on mt.tenant_code = m.tenant_code and mt.product_id=m.id WHERE mt.active_flag = '1' AND mt.relation_type = 'PRODUCT'
AND mt.tech_type = #{techType}
AND mt.product_id in
#{item}
AND mt.product_seq in
#{item}
order by a.sort asc,a.id asc

SELECT mt.id, mt.product_id , mt.product_seq, mt.tech_type, mt.tech_name FROM micro_technology mt WHERE mt.active_flag = '1' AND mt.relation_type = 'PRODUCT'
AND mt.product_id in
#{item}
AND mt.product_seq in
#{item}

SELECT mpc2.process_seq AS itemSeq, mpc2.process_name AS itemName, mpc2.process_code AS itemCode FROM micro_process_common mpc JOIN ( SELECT mp.process_id, mp.process_seq, mp.parent_process_id , mp.parent_process_seq, mp.tenant_code FROM micro_process_chain mp JOIN micro_technology mt ON mp.tenant_code = mt.tenant_code AND mp.tech_id = mt.id JOIN micro_product mpt ON mt.product_id = mpt.id AND mt.tenant_code = mpt.tenant_code WHERE mpt.product_code = #{productCode} ) AS t ON
mpc.tenant_code = t.tenant_code AND mpc.id = t.parent_process_id JOIN micro_process_common mpc2 ON mpc2.tenant_code = t.tenant_code AND mpc2.id = t.process_id WHERE mpc.process_code =#{preProcessCode}
mpc.tenant_code = t.tenant_code AND mpc.id = t.process_id JOIN micro_process_common mpc2 ON mpc2.tenant_code = t.tenant_code AND mpc2.id = t.parent_process_id WHERE mpc.process_code = #{operateProcessCode}

SELECT mt.product_seq as productSeq, mpc.process_seq AS operateProcessSeq, mpc.process_name AS operateProcessName, mpc.process_code AS operateProcessCode, max(mp.sort) as sort FROM micro_process_chain mp JOIN micro_technology mt ON mp.tenant_code = mt.tenant_code AND mp.tech_id = mt.id LEFT JOIN micro_process_common mpc ON mpc.tenant_code = mp.tenant_code AND mpc.id = mp.process_id WHERE mt.tech_type='STANDARD' AND mt.product_seq in
#{item}
group by mt.product_seq,mpc.process_seq, mpc.process_name,mpc.process_code order by sort

SELECT mt.product_seq FROM micro_technology mt WHERE mt.active_flag = '1' AND mt.relation_type = 'PRODUCT' AND mt.tech_type = 'STANDARD'
AND mt.product_id in
#{item}
AND mt.product_seq in
#{item}

select concat_ws('&',mp.product_seq,mp.id,mp.product_name) from micro_technology mt left join micro_product mp on mt.tenant_code = mp.tenant_code and mt.product_id= mp.id where mt.active_flag = '1' AND mt.relation_type = 'PRODUCT'
AND mt.tech_type = #{entity.techType}
AND mt.tech_pattern in
#{item}
group by mt.product_seq,mt.product_id

