product_id,
relation_type,
tech_type,
tech_pattern,
class_code,
class_name,
tenant_code,
created_by,
last_upd_by
)
VALUES

    (
    #{entity.id}
    ,#{entity.techCode}
    ,#{entity.techName}
    ,#{entity.techGroup}
    ,#{entity.techDesc}
    ,#{entity.techVersion}
    ,#{entity.productSeq}
    ,#{entity.productId}
    ,#{entity.relationType}
    ,#{entity.techType}
    ,#{entity.techPattern}
    ,#{entity.classCode}
    ,#{entity.className}
    ,#{entity.tenantCode}
