    ,#{entity.lastUpdBy}
    )

mapper.update:
update micro_technology
tech_code = #{techCode}, tech_name = #{techName}, tech_group = #{techGroup}, tech_desc = #{techDesc}, tech_version = #{techVersion}, product_seq = #{productSeq}, product_id = #{productId}, relation_type = #{relationType}, tech_type = #{techType}, tech_pattern = #{techPattern}, class_code = #{classCode}, class_name = #{className}, tenant_code = #{tenantCode}, created_by = #{createdBy}, created_date = #{createdDate}, last_upd_by = #{lastUpdBy}, last_upd_date = #{lastUpdDate}, active_flag = #{activeFlag},
where id = #{id}

